import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map } from 'rxjs';
import { Curso } from '../models/curso.model';

@Injectable({ providedIn: 'root' })
export class CursoService {
  // ── CONFIGURACIÓN OBLIGATORIA ─────────────────────────────────────────────
  // 1. Entra a https://crudcrud.com/
  // 2. Copia el endpoint que te genera (algo como .../api/3f9a1c2b...)
  // 3. Pégalo aquí abajo reemplazando 'TU_ENDPOINT_AQUI'
  // Nota: el endpoint gratuito de crudcrud expira a las 24 horas o al llegar
  // a 100 registros en un mismo recurso. Si deja de responder, genera uno nuevo.
  private readonly baseUrl =
    'https://crudcrud.com/api/TU_ENDPOINT_AQUI/cursos';

  constructor(private http: HttpClient) {}

  listar(): Observable<Curso[]> {
    return this.http.get<Curso[]>(this.baseUrl);
  }

  obtener(id: string): Observable<Curso> {
    return this.http.get<Curso>(`${this.baseUrl}/${id}`);
  }

  crear(curso: Curso): Observable<Curso> {
    const { _id, ...data } = curso;
    return this.http.post<Curso>(this.baseUrl, data);
  }

  actualizar(id: string, curso: Curso): Observable<void> {
    const { _id, ...data } = curso;
    // crudcrud responde 200 sin cuerpo en PUT/DELETE; pedir texto evita que
    // HttpClient intente parsear una respuesta vacía como JSON y falle.
    return this.http
      .put(`${this.baseUrl}/${id}`, data, { responseType: 'text' })
      .pipe(map(() => undefined));
  }

  eliminar(id: string): Observable<void> {
    return this.http
      .delete(`${this.baseUrl}/${id}`, { responseType: 'text' })
      .pipe(map(() => undefined));
  }
}
